INSERT INTO levers VALUES('A','System prompt','done','lever-a-*','Identity/size/markup/autonomy differ. Copilot CLI "non-interactive, proceed autonomously"; Claude (both) "confirm before irreversible". Claude pair share 1 SDK template (sdk-cli vs sdk-ts; TaskCreate vs TodoWrite). VS Code Copilot biggest (44k) via inlined repo instructions.');
INSERT INTO levers VALUES('B','Dynamic context injection','done','lever-b-*','All inject runtime context but at different points. Copilot CLI <environment_context> in system (cwd/repo/OS). Claude CLI injects userEmail+date+skills in FIRST USER MSG reminder. Claude-in-VSCode injects # Environment + gitStatus/recent commits in system. VS Code Copilot: minimal/none.');
INSERT INTO levers VALUES('C','Tool catalog & schema design','done','lever-c-*','Naming is DISCRETION not locked: Copilot CLI snake_case (bash/view/edit), Claude SDK PascalCase (Bash/Read/Edit), MCP dotted (mcp__server__tool). Copilot CLI 19 tools ~8.1k. Claude CLI 27 tools ~18.9k (flat; avg desc 2145 chars - very verbose). Claude-in-VSCode 27 native + ~220 MCP = 247 (483-char descs). Tool defs 54-93% of prefix.');
INSERT INTO levers VALUES('D','Tool delivery / virtualization','done','lever-d-*','Copilot CLI flat 19 (54%); Claude CLI flat 27 (69%). VS Code Copilot VIRTUALIZES via deferred_tools_delta (progressive 0->1->23). Claude-in-VSCode flat & HUGE: 247 tools (89%), Insider 401 (93%) — because MCP was ON there.');
INSERT INTO levers VALUES('E','Skills','done','lever-e-*','VS Code Copilot 37 skills FULL in system prompt (taxes every call). Claude CLI & Claude-in-VSCode 13 skills via first-user-msg <system-reminder>+Skill tool (on-demand). Copilot CLI: skill tool + <available_skills>. CONFIRMS draft wrong: Claude has 13 not 0.');
INSERT INTO levers VALUES('F','MCP','done','lever-f-*','CLIs MCP-OFF (Copilot log "0 servers"; Claude mcpInstructions empty). VS Code harnesses MCP-ON: hi18=12 servers, Claudeok=8, Insider=9 (Azure/github/playwright/bicep/pylance...). So IDE captures NOT MCP-matched to CLIs — explains big prefixes.');
INSERT INTO levers VALUES('G','Memory / persistence philosophy','done','lever-g-*','Claude (both) ship elaborate file-based auto-memory (user/feedback/project types, [[cross-links]], memory dir). Copilot CLI: session SQL todos + plan.md (session-isolated, no cross-session). VS Code Copilot: scoped /memories/ (user/session/repo), brevity-capped, 200-line auto-load.');
INSERT INTO levers VALUES('H','Conversation-history management','done','lever-h-*','Stateless full-prefix resend LOCKED (all harnesses re-send system+tools every turn). DISCRETION: Copilot CLI linear msg growth, no visible compaction, no context-mgmt note. Claude CLI msgs 1325->8090 tok with a plateau at req 13 (opaque summarization) + EXPLICIT "# Context management" system section. VS Code exports lack wire bodies.');
INSERT INTO levers VALUES('I','Prompt-caching strategy','done','lever-i-*','Mechanism locked (ephemeral, <=4 breakpoints). Copilot CLI ~3 breakpoints (system/tools/rolling) hit 87.2%. Claude CLI hit 90.2% (relay hides breakpoints). VS Code captures cold-start single-turn so 0-12% (not meaningful).');
INSERT INTO levers VALUES('J','Sampling / generation params','done','lever-j-*','Copilot CLI max_tokens 8192, temp 1. Claude CLI max_tokens 32000, temp unset(default). VS Code exports do not expose sampling params (only maxResponseTokens/maxPromptTokens). hi18 fired gpt-4o-mini aux requests + claude-sonnet-4.5 agent turn.');
INSERT INTO levers VALUES('K','Reasoning / thinking','done','lever-k-*','Copilot CLI thinking enabled EVERY turn {budget 1024, summarized} (580 reasoning tok). Claude CLI: no thinking param in relay yet 1 thinking block in transcript (~103 tok) -> likely interleaved-thinking via beta header (stripped by relay). VS Code: 0 reasoning tokens (off).');
INSERT INTO levers VALUES('L','Agent loop / orchestration','done','lever-l-*','Copilot CLI: task + read_agent/list_agents (manager framing). Claude (both): big fleet Agent+Task*+EnterPlanMode+Cron*+Worktree+Monitor+Schedule/Push/Remote. VS Code Copilot: 11 named agents catalog via runSubagent. All 4 push parallel tool calls.');
INSERT INTO levers VALUES('M','Safety / policy / platform','done','lever-m-*','Trained floor locked. Copilot CLI adds <prohibited_actions>+<shell_security>+org content-exclusion (secrets.json blocked at runtime). Claude (both): dual-use security preamble + autonomy "care" gating. VS Code Copilot: minimal Microsoft content-policy clause.');
INSERT INTO levers VALUES('N','Model routing & transport','done','lever-n-*','All resolve claude-sonnet-4-5-20250929. Copilot CLI labels "claude-sonnet-4.5" via GitHub proxy. Claude CLI direct (cc_entrypoint=sdk-cli). Claude-in-VSCode via Copilot proxy (sdk-ts). VS Code Copilot agent turn=claude-sonnet-4.5 + gpt-4o-mini aux calls.');
INSERT INTO levers VALUES('O','Metering / telemetry','done','lever-o-*','Copilot CLI: EXACT native GitHub AI credits (16.3cr/$0.163). Claude CLI: no native meter -> token-normalized estimate (~$0.50) + sends metadata.user_id (device/account/session) + billing header in system. VS Code exports: billing/usage stripped (null).');
